import React from 'react';
import './Navbar.css';
import { Link } from 'react-router-dom';

const Navbar = ({ isLoggedIn, handleLogout }) => {
  return (
    <div className='nav'>
      <h1>Troop Tracker</h1>
      
      <div className='anchors'>
        <Link to='/'>Home</Link>
        <a className='dropdown' href='#services'>
          Units <i className="fa-solid fa-angle-down"></i>
          <div className='content'>
            <Link to='/army'>Army</Link>
            <Link to='/airforce'>Air Force</Link>
            <Link to='/navy'>Navy</Link>
            <Link to='/marines'>Marines</Link>
          </div>
        </a>
        <Link to='/about'>About</Link>

        {/* Conditionally render Login/Signup or Logout button */}
        {!isLoggedIn ? (
          <Link className='btn' to='/login'>Login/Signup</Link>
        ) : (
          <button className='btn' onClick={handleLogout}>Logout</button>
        )}
      </div>
    </div>
  );
};

export default Navbar;
